    plugin: &PluginSummary,
    marketplace_label: Option<&str>,
    status_label_width: usize,
) -> String {
    let status_label = plugin_status_label(plugin);
    let status_label = format!("{status_label:<status_label_width$}");
    match (marketplace_label, plugin_description(plugin)) {
        (Some(marketplace_label), Some(description)) => {
            format!("{status_label} · {marketplace_label} · {description}")
        }
        (Some(marketplace_label), None) => format!("{status_label} · {marketplace_label}"),
        (None, Some(description)) => format!("{status_label} · {description}"),
        (None, None) => status_label,
    }
}

/// Tab ID for a marketplace-specific tab, derived from its file system path so
/// tabs with duplicate display names can still be addressed individually.
fn marketplace_tab_id(marketplace: &PluginMarketplaceEntry) -> String {
    format!("marketplace:{}", marketplace.path.display())
}

/// Ensure a tab always has at least one (disabled) row so it renders cleanly
/// even when it contains no plugins.
fn plugins_tab_items_or_placeholder(items: Vec<SelectionItem>) -> Vec<SelectionItem> {
    if items.is_empty() {
        vec![SelectionItem {
            name: "No plugins available".to_string(),
            description: Some("No plugins are available on this tab.".to_string()),
            is_disabled: true,
            ..Default::default()
        }]
    } else {
        items
    }
